from pathlib import Path
import json,csv
root=Path(__file__).parent
with (root/'route_monthly_actuals.csv').open() as f: actual=list(csv.DictReader(f))
with (root/'capacity_scenarios.csv').open() as f: future=list(csv.DictReader(f))
with (root/'backtest_scores.csv').open() as f: scores=list(csv.DictReader(f))
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Airline Route Demand & Capacity | Ella Simeon</title><style>
:root{font-family:Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;color:#14233c;background:#f2f6fb}*{box-sizing:border-box}body{margin:0}.wrap{max-width:1190px;margin:auto;padding:32px 24px 65px}header{background:linear-gradient(125deg,#071c3b,#154779);color:white}header .wrap{padding-top:42px;padding-bottom:45px}.eyebrow{color:#79d8ef;font-size:12px;letter-spacing:.14em;font-weight:800;text-transform:uppercase}h1{font-size:clamp(32px,4.8vw,54px);letter-spacing:-.045em;line-height:1.1;margin:13px 0}header p{max-width:730px;color:#d3e1f3;line-height:1.6}.pill{display:inline-block;padding:8px 12px;background:#ffffff20;border:1px solid #ffffff30;border-radius:30px;font-size:12px;font-weight:700}.toolbar{display:flex;align-items:center;gap:14px;margin:24px 0}.toolbar label{font-weight:800;font-size:13px}.toolbar select{border:1px solid #c9d7e6;border-radius:10px;padding:12px 15px;background:white;font-size:16px;font-weight:700;color:#17385c;min-width:180px}.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.card,.panel{background:white;border:1px solid #dce6f1;border-radius:16px;box-shadow:0 6px 25px #0b2d570a}.card{padding:20px}.label{font-weight:800;color:#63748c;text-transform:uppercase;letter-spacing:.07em;font-size:11px}.value{font-size:29px;font-weight:850;letter-spacing:-.035em;margin:12px 0 5px}.note{font-size:12px;color:#667991}h2{font-size:23px;letter-spacing:-.025em;margin:35px 0 14px}.panel{padding:24px}.grid{display:grid;grid-template-columns:1.5fr 1fr;gap:17px}.legend{font-size:12px;color:#667991;display:flex;gap:20px;flex-wrap:wrap;margin:4px 0 15px}.swatch{display:inline-block;width:16px;height:4px;vertical-align:middle;margin-right:6px;border-radius:3px}.blue{background:#087dc2}.teal{background:#15b6ab}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:17px}.barline{display:grid;grid-template-columns:70px 1fr 75px;align-items:center;gap:10px;margin:14px 0;font-size:13px}.bar{height:19px;border-radius:5px;background:#eaf0f7;overflow:hidden}.bar div{height:100%;background:#14a7c3;border-radius:5px}.callout{background:#edf7ff;border-left:4px solid #1287bc;border-radius:9px;padding:18px;line-height:1.6;color:#234266}table{width:100%;border-collapse:collapse;font-size:13px}td,th{padding:12px 9px;border-bottom:1px solid #e8eef5;text-align:left}th{color:#61738b;font-size:11px;text-transform:uppercase;letter-spacing:.04em}td:last-child,th:last-child{text-align:right}.risk{color:#b56b25;font-weight:700}.ok{color:#148577;font-weight:700}.small{color:#64748b;font-size:12px;line-height:1.6}.axis{font-size:11px;fill:#75869b}@media(max-width:900px){.kpis{grid-template-columns:repeat(2,1fr)}.grid,.grid2{grid-template-columns:1fr}}@media(max-width:550px){.kpis{grid-template-columns:1fr}.panel{overflow-x:auto}table{min-width:630px}}
</style></head><body><header><div class="wrap"><div class="eyebrow">Ella Simeon · Airline analytics portfolio</div><h1>Route Demand & Capacity Forecast</h1><p>Which nonstop markets may need a closer capacity review? Explore actual passenger traffic, tested forecasts, and seat planning scenarios across six JetBlue-operated routes.</p><span class="pill">Public BTS T-100 data · Independent analysis · Not a JetBlue business recommendation</span></div></header><main class="wrap"><div class="toolbar"><label for="route">Route</label><select id="route"></select></div><div class="kpis"><div class="card"><div class="label">Latest actual month</div><div class="value">Apr 2026</div><div class="note">Latest month in this source extract</div></div><div class="card"><div class="label">Forecast passengers</div><div class="value" id="forecast"></div><div class="note">May–Aug 2026 total</div></div><div class="card"><div class="label">2025 holdout error</div><div class="value" id="wape"></div><div class="note">Weighted absolute percentage error</div></div><div class="card"><div class="label">Capacity review</div><div class="value" id="review"></div><div class="note">Against 2025 seats and an 85% illustrative target</div></div></div><h2>Passenger demand over time</h2><div class="grid"><div class="panel"><div class="legend"><span><i class="swatch blue"></i>Actual passengers</span><span><i class="swatch teal"></i>Forecast passengers</span></div><svg id="chart" viewBox="0 0 680 270" role="img" aria-label="Monthly actual passengers and forecast"></svg><p class="small">Forecast starts May 2026. The lighter range is ± the route's 2025 holdout WAPE, an error scenario rather than a formal prediction interval.</p></div><div class="panel"><h3>What the backtest says</h3><div class="callout" id="interpret"></div><p class="small" id="method"></p></div></div><h2>Four month capacity scenario</h2><div class="panel"><table><thead><tr><th>Month</th><th>Forecast passengers</th><th>2025 seats</th><th>Seats at 85%</th><th>Seat gap</th></tr></thead><tbody id="months"></tbody></table><p class="small">Seat gap = required seats at a hypothetical 85% passenger-to-seat target minus seats supplied in the same 2025 month. Positive values suggest a capacity review. This does not account for price, yield, schedules, fleet, connecting traffic, or profitability.</p></div><h2>Comparison across six routes</h2><div class="grid2"><div class="panel"><h3>2025 forecast error</h3><div id="routes"></div></div><div class="panel"><h3>Decision context</h3><p class="small">The baseline repeats passenger counts from the same month one year earlier. A seasonal growth variant applies a capped year-over-year factor. The lower-error method on a 2024 validation year is selected for each route; 2025 remains untouched until the final holdout evaluation.</p><p class="small">Operational decisions would also need current seat schedules, fares, revenue, competitive supply, and margin. The BTS counts describe passengers carried, which can be constrained by seats offered; they are not an unconstrained demand estimate.</p></div></div><p class="small">Data lineage: Bureau of Transportation Statistics T-100 scheduled passenger segments, accessed via the processed route_carrier_month release of the independent T100 Route Explorer project. Six domestic directional routes only; 2022–April 2026. Analysis by Ella Simeon.</p></main><script>const actual=__ACTUAL__,future=__FUTURE__,scores=__SCORES__;const $=id=>document.getElementById(id),fmt=x=>Math.round(+x).toLocaleString(),pct=x=>(100*(+x)).toFixed(1)+'%';const sel=$('route');scores.forEach(x=>sel.add(new Option(x.route,x.route)));
function line(points,color,dash=''){return `<polyline points="${points.map((p,i)=>`${p.x},${p.y}`).join(' ')}" fill="none" stroke="${color}" stroke-width="3" stroke-linejoin="round" stroke-linecap="round" ${dash?'stroke-dasharray="'+dash+'"':''}/>`}
function render(){const route=sel.value,s=scores.find(x=>x.route===route),a=actual.filter(x=>x.route===route&&x.flight_month>='2025-01-01'),f=future.filter(x=>x.route===route),total=f.reduce((v,x)=>v+(+x.forecast_passengers),0),gap=f.reduce((v,x)=>v+(+x.seat_gap_vs_prior_year),0);$('forecast').textContent=fmt(total);$('wape').textContent=pct(s.holdout_2025_wape);$('review').textContent=gap>0?'Review':'Monitor';$('review').style.color=gap>0?'#b56b25':'#148577';$('interpret').innerHTML=gap>0?`<strong>${fmt(gap)} additional seats across four months</strong> would meet the illustrative 85% benchmark relative to last year's supplied seats. Investigate current schedules and revenue before changing capacity.`:`<strong>No additional seats indicated</strong> versus last year's supply under the illustrative 85% benchmark. Continue monitoring booking pace and realized load factors.`;$('method').innerHTML=`Selected model: <strong>${s.selected_method}</strong>. 2025 WAPE: <strong>${pct(s.holdout_2025_wape)}</strong>; seasonal-naive baseline: <strong>${pct(s.holdout_2025_baseline_wape)}</strong>. ${+s.holdout_2025_wape>.2?'Forecast error is high on this route, so treat its seat scenario with particular caution.':''}`;$('months').innerHTML=f.map(x=>`<tr><td>${x.month.slice(0,7)}</td><td>${fmt(x.forecast_passengers)}</td><td>${fmt(x.prior_year_seats)}</td><td>${fmt(x.seats_at_85pct)}</td><td class="${+x.seat_gap_vs_prior_year>0?'risk':'ok'}">${+x.seat_gap_vs_prior_year>0?'+':''}${fmt(x.seat_gap_vs_prior_year)}</td></tr>`).join('');$('routes').innerHTML=scores.map(x=>`<div class="barline"><strong>${x.route}</strong><div class="bar"><div style="width:${Math.min(100,(+x.holdout_2025_wape)/.32*100)}%"></div></div><span>${pct(x.holdout_2025_wape)}</span></div>`).join('');const vals=a.map(x=>+x.passengers).concat(f.map(x=>+x.scenario_high)),max=Math.ceil(Math.max(...vals)/10000)*10000,min=0;const xx=i=>38+i*(622/(a.length+f.length-1)),yy=v=>226-(v-min)/(max-min)*188,ap=a.map((x,i)=>({x:xx(i),y:yy(+x.passengers)})),fp=f.map((x,i)=>({x:xx(a.length+i),y:yy(+x.forecast_passengers)})),start={x:xx(a.length-1),y:yy(+a[a.length-1].passengers)};let svg='';for(let i=0;i<4;i++){let v=max*i/3,y=yy(v);svg+=`<line x1="38" y1="${y}" x2="660" y2="${y}" stroke="#e8eef5"/><text class="axis" x="0" y="${y+4}">${Math.round(v/1000)}k</text>`}const upper=f.map((x,i)=>`${xx(a.length+i)},${yy(+x.scenario_high)}`).join(' '),lower=f.slice().reverse().map((x,j)=>`${xx(a.length+f.length-1-j)},${yy(+x.scenario_low)}`).join(' ');svg+=`<polygon points="${upper} ${lower}" fill="#c2f0e9" opacity=".65"/>`+line(ap,'#087dc2')+line([start,...fp],'#15b6ab');for(const idx of [0,6,12,15]){const label=idx<a.length?a[idx].flight_month:f[idx-a.length].month;svg+=`<text class="axis" x="${xx(idx)-21}" y="255">${label.slice(0,7)}</text>`}$('chart').innerHTML=svg}sel.addEventListener('change',render);render();</script></body></html>'''
(root/'dashboard.html').write_text(html.replace('__ACTUAL__',json.dumps(actual,separators=(',',':'))).replace('__FUTURE__',json.dumps(future,separators=(',',':'))).replace('__SCORES__',json.dumps(scores,separators=(',',':'))))
